def f(g):
    H,W=len(g),len(g[0])
    cells={(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x==4}
    marks=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x==6]
    r0=min(i for i,j in cells); c0=min(j for i,j in cells)
    rb=max(i for i,j in cells); cb=max(j for i,j in cells)
    out=[[x for x in row] for row in g]
    h=rb-r0+1; w=cb-c0+1
    below = min(m[0] for m in marks)>=rb; right = min(m[1] for m in marks)>=cb
    for i,j in cells:
        o=(i+(h if below else 0), j+(w if right else 0))
        out[o[0]][o[1]]=4
    for m in marks: out[m[0]][m[1]]=0
    return out
